me\":\"Approximately 20 mins\"},{\"name\":\"The British School Al Khubairat\",\"time\":\"Approximately 15 mins\"}]},{\"name\":\"Landmarks\",\"items\":[{\"name\":\"Abu Dhabi International Airport\",\"time\":\"Approximately 20 mins\"},{\"name\":\"Downtown Abu Dhabi\",\"time\":\"Approximately 15 mins\"}]}]}\";s:10:\"created_at\";s:19:\"2026-10-21 14:31:36\";s:10:\"updated_at\";s:19:\"2026-11-06 11:06:18\";}s:11:\"\0*\0original\";a:9:{s:2:\"id\";i:57;s:7:\"page_id\";i:4;s:11:\"section_key\";s:8:\"location\";s:12:\"section_name\";s:23:\"Location & Connectivity\";s:5:\"order\";i:9;s:9:\"is_active\";i:1;s:7:\"content\";s:1101:\"{\"title\":\"Wadeem Gardens Location & Attractions\",\"subtitle\":\"Wadeem Gardens is located on Karachi, Pakistan, with restaurants, schools and healthcare facilities accessible from the island.\",\"image\":\"\\/images\\/20231014_191447.webp\",\"categories\":[{\"name\":\"Restaurants\",\"items\":[{\"name\":\"Marmoura Restaurant & Lounge\",\"time\":\"Approximately 4 mins\"},{\"name\":\"The Plage Restaurant\",\"time\":\"Approximately 4 mins\"},{\"name\":\"Rain Cafe Hudayriat\",\"time\":\"Approximately 5 mins\"},{\"name\":\"Souvlaki Nation\",\"time\":\"Approximately 6 mins\"},{\"name\":\"Nalu Restaurant & Lounge\",\"time\":\"Approximately 8 mins\"}]},{\"name\":\"Hospitals & Clinics\",\"items\":[{\"name\":\"Burjeel Medical Center\",\"time\":\"Approximately 15 mins\"},{\"name\":\"Cleveland Clinic Abu Dhabi\",\"time\":\"Approximately 20 mins\"}]},{\"name\":\"Schools\",\"items\":[{\"name\":\"Cranleigh Abu Dhabi\",\"time\":\"Approximately 20 mins\"},{\"name\":\"The British School Al Khubairat\",\"time\":\"Approximately 15 mins\"}]},{\"name\":\"Landmarks\",\"items\":[{\"name\":\"Abu Dhabi International Airport\",\"time\":\"Approximately 20 mins\"},{\"name\":\"Downtown Abu Dhabi\",\"time\":\"Approximately 15 mins\"}]}]}\";s:10:\"created_at\";s:19:\"2026-10-21 14:31:36\";s:10:\"updated_at\";s:19:\"2026-11-06 11:06:18\";}s:10:\"\0*\0changes\";a:0:{}s:11:\"\0*\0