(46, 'contact_subtitle', 'contact', 'Subtitle Paragraph', 'textarea', 'Discover exceptional residential apartments, modern villas, and prime properties across Saima Group developments. Connect with our dedicated sales and advisory team for personalized guidance and project details.', '2026-10-20 04:11:47', '2026-11-06 06:37:46'),
