(55, 4, 'about', 'About Community', 3, 1, '{\"tag\":\"ABOUT COMMUNITY\",\"heading\":\"Coastal Luxury Living\",\"description\":\"A prestigious residential destination on Saima offering unparalleled coastal grandeur, active outdoor living, and bespoke modern architecture.\",\"image\":\"\\/images\\/wadeem-gardens\\/amenity-club.png\",\"title\":\"Wadeem Gardens by Saima Group\",\"video_url\":null,\"video_poster\":\"\\/images\\/wadeem-gardens\\/video-poster.png\"}', '2026-10-21 09:31:36', '2026-11-06 07:35:33'),
