(579, 76, 'about', 'About punjab', 4, 1, '{\"title\":\"About the Community\",\"description\":\"A meticulously planned coastal sanctuary seamlessly integrating contemporary luxury living with untouched nature. Spanning scenic waterfronts, lush mangroves, and cycling corridors, the master community offers an unmatched urban lifestyle for residents and high-yield potential for global real estate investors.\",\"video_poster\":\"\\/images\\/projects\\/poster.jpg\",\"video_src\":\"\\/images\\/nawayef-park-views\\/asset_15.mp4\",\"heading\":\"About the Community\",\"video_url\":\"https:\\/\\/stream.mux.com\\/A3200aZtT5Wq7VlYwQv3wP9W2hX8.m3u8\",\"poster_image\":\"\\/images\\/projects\\/poster.jpg\"}', '2026-10-30 01:57:40', '2026-10-30 01:57:40'),
(580, 76, 'faq', 'Frequently Asked Questions', 5, 1, '{\"title\":\"Frequently Asked Questions\",\"description\":\"<p>Key information and helpful answers regarding punjab and property purchases on Saima.<\\/p>\",\"items\":[{\"q\":\"Are properties in this city freehold for foreign and overseas investors?\",\"a\":\"Yes, designated luxury master developments offer 100% freehold ownership for local and international buyers with complete title deed registration.\"},{\"q\":\"What are the typical payment plans available?\",\"a\":\"Flexible installment plans are offered typically linked to construction milestones, with down payments starting from 5% to 10%.\"}],\"heading\":\"Frequently Asked Questions\",\"subtitle\":\"Find answers to common questions about properties, buying process, and payment plans.\"}', '2026-10-30 01:57:40', '2026-11-06 04:52:50'),
(581, 76, 'contact', 'Contact & Booking CTA', 6, 1, '{\"title\":\"Register Your Interest in punjab\",\"subtitle\":\"Connect with our dedicated city property advisors for personalized availability, floor plans, and VIP access.\",\"button_text\":\"REGISTER INTEREST\",\"phone\":\"+971 2 000 0000\",\"email\":\"info@saimaprojects.com\"}', '2026-10-30 01:57:40', '2026-11-06 04:52:50'),
