(756, 93, 'amenities', 'Amenities & Facilities', 4, 1, '{\"title\":\"Wadeem Gardens Amenities\",\"subtitle\":\"Wadeem Gardens provides spaces that support everyday convenience, recreation, social connection, and family living. Residents can access essential services, leisure destinations, and community spaces within the wider development, while the waterfront setting and connected community environment support an active and convenient lifestyle.\",\"items\":[]}', '2026-11-01 07:49:56', '2026-11-05 04:10:43'),
